#define SECONDARY_STACK_ALIGN_BYTES       8
#define SECONDARY_STACK_ALIGN_SLACK       7
#define SECONDARY_STACK_HEADER_BYTES      16
#define SECONDARY_STACK_CAPACITY_OFFSET   8
#define SECONDARY_STACK_MARK_TYPE         "{ ptr, i64, i64 }"
#define VALUE_RESULT_MAX_BYTES            64
#define SECONDARY_STACK_FIRST_CHUNK_BYTES 16384
#define SECONDARY_STACK_MAX_CHUNK_BYTES   8388608

_Static_assert (SECONDARY_STACK_ALIGN_BYTES * Bits_Per_Unit >= Width_64,
  "the secondary stack must align the widest scalar it carries");
_Static_assert (SECONDARY_STACK_ALIGN_SLACK
                == SECONDARY_STACK_ALIGN_BYTES - 1,
  "the rounding slack is spelled out for stringification, checked here");
_Static_assert (SECONDARY_STACK_HEADER_BYTES % SECONDARY_STACK_ALIGN_BYTES == 0,
  "a chunk's payload begins at its header's end and must stay aligned");
_Static_assert (SECONDARY_STACK_FIRST_CHUNK_BYTES
                <= SECONDARY_STACK_MAX_CHUNK_BYTES,
  "chunks grow from the first size towards the cap");

#define SECONDARY_STACK_CAPACITY(name, chunk)                              \
  "  %" name "_slot = getelementptr inbounds i8, ptr " chunk ", i64 "      \
    TEXT_OF (SECONDARY_STACK_CAPACITY_OFFSET) "\n"                         \
  "  %" name " = load i64, ptr %" name "_slot\n"

#define SECONDARY_STACK_PUBLISH_LIMIT(name, chunk)                         \
  SECONDARY_STACK_CAPACITY (name "_capacity", chunk)                       \
  "  %" name "_payload = getelementptr inbounds i8, ptr " chunk ", i64 "   \
    TEXT_OF (SECONDARY_STACK_HEADER_BYTES) "\n"                            \
  "  %" name "_base = ptrtoint ptr %" name "_payload to i64\n"             \
  "  %" name "_limit = add i64 %" name "_base, %" name "_capacity\n"       \
  "  store i64 %" name "_limit, ptr @__ss_limit\n"

