#define ASPECT_KIND_LIST(_)                                                                        \
  _ (ASPECT_INLINE,        "INLINE",        ASPECT_ARGUMENT_BOOLEAN,    ASPECT_LANGUAGE_DEFINED,       \
     ASPECT_ROUTE_PRAGMA,                ASPECT_ON_SUBPROGRAM | ASPECT_ON_GENERIC_SUBPROGRAM |     \
                                         ASPECT_ON_PROTECTED_OPERATION)                            \
