#define PREDEFINED_EXCEPTION_OPERATION_LIST(_)                                \
  _ ("FUNCTION EXCEPTION_NAME (ID : EXCEPTION_ID) RETURN STRING;",            \
     "__ada_exception_name")                                                  \
  _ ("FUNCTION EXCEPTION_NAME (X : EXCEPTION_OCCURRENCE) RETURN STRING;",     \
     "__ada_exception_occurrence_name")                                       \
  _ ("FUNCTION EXCEPTION_MESSAGE (X : EXCEPTION_OCCURRENCE) RETURN STRING;",  \
     "__ada_exception_message")                                               \
  _ ("FUNCTION EXCEPTION_INFORMATION (X : EXCEPTION_OCCURRENCE) "             \
     "RETURN STRING;",                                                        \
     "__ada_exception_information")                                           \
  _ ("FUNCTION EXCEPTION_IDENTITY (X : EXCEPTION_OCCURRENCE) "                \
     "RETURN EXCEPTION_ID;",                                                  \
     "__ada_exception_identity")                                              \
  _ ("PROCEDURE RAISE_EXCEPTION (E : EXCEPTION_ID; "                          \
