#define PREDICATE_USE_LIST(_)                                                 \
  _ (PREDICATE_USE_INDEX,     true,  false, true,                             \
     "it cannot be an index subtype, nor the range of an index constraint " \
     "or of a slice")                                                         \
  _ (PREDICATE_USE_AGGREGATE, false, true,  true,                             \
     "it cannot be a choice of an array aggregate")                           \
  _ (PREDICATE_USE_ITERATION, false, true,  true,                             \
     "a for loop cannot iterate over it")                                     \
  _ (PREDICATE_USE_CHOICE,    false, false, false,                            \
     "it cannot be a choice of a case statement, a case expression or a "    \
