typedef enum {
  STATICNESS_STATIC = 0,
  STATICNESS_NOT_A_SCALAR_TYPE,
  STATICNESS_NOT_A_STATIC_PRIMARY,
  STATICNESS_TYPE_CONVERSION,
  STATICNESS_NOT_A_PREDEFINED_OPERATION,
  STATICNESS_ATTRIBUTE_OF_A_NONSTATIC_SUBTYPE,
  STATICNESS_QUALIFIED_BY_A_NONSTATIC_SUBTYPE,
  STATICNESS_EVALUATION_RAISES,
  STATICNESS_USER_DEFINED_LITERAL,
  STATICNESS_QUANTIFIED_EXPRESSION
} Staticness_Kind;

const char *const Staticness_Explanation[] = {
  [STATICNESS_STATIC] =
    "is static",
  [STATICNESS_NOT_A_SCALAR_TYPE] =
    "is not of a scalar type",
  [STATICNESS_NOT_A_STATIC_PRIMARY] =
    "names something other than a literal, a named number, a static constant, "
    "an attribute of a static subtype, a qualified expression of a static "
    "subtype or a predefined operator applied to static operands",
  [STATICNESS_TYPE_CONVERSION] =
    "is a type conversion, which is not a static primary (a qualified "
    "expression of a static subtype is)",
  [STATICNESS_NOT_A_PREDEFINED_OPERATION] =
    "applies an operation that is not a predefined operator",
  [STATICNESS_ATTRIBUTE_OF_A_NONSTATIC_SUBTYPE] =
    "takes an attribute of a prefix that is not a static subtype",
  [STATICNESS_QUALIFIED_BY_A_NONSTATIC_SUBTYPE] =
    "is qualified by a subtype that is not static",
  [STATICNESS_EVALUATION_RAISES] =
    "raises an exception when evaluated rather than delivering a value",
  [STATICNESS_USER_DEFINED_LITERAL] =
    "is a user-defined literal, which stands for a call of the function its "
    "type's literal aspect names, and a function call is never static",
  [STATICNESS_QUANTIFIED_EXPRESSION] =
    "is a quantified expression, whose value comes from evaluating its "
    "predicate for each value of its loop parameter, and a quantified "
    "expression is never static",
};

