#define For_Each_Generic_Actual(instance, slot)                                \
  for (Generic_Actual_Binding *slot = (instance)->actual_bindings,             \
                              *slot##_end =                                    \
                                slot ? slot + (instance)->actual_binding_count \
                                     : slot;                                   \
       slot != slot##_end; slot++)

