typedef struct {
  const char               *spelling;
  Dialect_Match_Kind        match;
  Dialect_Disposition_Kind  disposition;
  Dialect_Effect_Kind       effect;
  const char               *mapped;
} Dialect_Flag_Properties;

#define DIALECT_FLAG_ROW(row_spelling, row_match, row_disposition,            \
                         row_effect, row_mapped)                              \
  { .spelling    = row_spelling,                                              \
    .match       = DIALECT_MATCH_##row_match,                                 \
    .disposition = DIALECT_##row_disposition,                                 \
    .effect      = DIALECT_EFFECT_##row_effect,                               \
    .mapped      = row_mapped },
const Dialect_Flag_Properties Gnat_Flag_Table[] = {
  GNAT_FLAG_LIST (DIALECT_FLAG_ROW)
};
const Dialect_Flag_Properties Ghs_Flag_Table[] = {
  GHS_FLAG_LIST (DIALECT_FLAG_ROW)
};
#undef DIALECT_FLAG_ROW
enum { GNAT_FLAG_COUNT = sizeof Gnat_Flag_Table / sizeof *Gnat_Flag_Table };
enum { GHS_FLAG_COUNT  = sizeof Ghs_Flag_Table  / sizeof *Ghs_Flag_Table  };
_Static_assert (GNAT_FLAG_COUNT == 30, "GNAT_FLAG_LIST row count");
_Static_assert (GHS_FLAG_COUNT  == 17, "GHS_FLAG_LIST row count");

typedef enum {
  DIALECT_LETTER_ENABLE_ALL,
  DIALECT_LETTER_ENABLE,
  DIALECT_LETTER_DISABLE,
  DIALECT_LETTER_SILENCE
} Dialect_Letter_Action;

#define DIALECT_WARNING_SET_ALL       ((1u << WARNING_CLASS_COUNT) - 1)
#define DIALECT_WARNING_SET_UNUSED                                            \
  (1u << WARNING_UNUSED_VARIABLE  | 1u << WARNING_UNUSED_BUT_SET_VARIABLE     \
 | 1u << WARNING_UNUSED_PARAMETER | 1u << WARNING_UNUSED_WITH)
#define DIALECT_WARNING_SET_REDUNDANT (1u << WARNING_REDUNDANT_WITH)
#define DIALECT_WARNING_SET_PRAGMA    (1u << WARNING_UNRECOGNIZED_PRAGMA)

#define GNAT_WARNING_LETTER_LIST(_)                                           \
  _ ('a', ENABLE_ALL, DIALECT_WARNING_SET_ALL)                                \
  _ ('A', DISABLE,    DIALECT_WARNING_SET_ALL)                                \
  _ ('s', SILENCE,    0u)                                                     \
  _ ('u', ENABLE,     DIALECT_WARNING_SET_UNUSED)                             \
  _ ('U', DISABLE,    DIALECT_WARNING_SET_UNUSED)                             \
  _ ('r', ENABLE,     DIALECT_WARNING_SET_REDUNDANT)                          \
  _ ('R', DISABLE,    DIALECT_WARNING_SET_REDUNDANT)                          \
  _ ('g', ENABLE,     DIALECT_WARNING_SET_PRAGMA)                             \
  _ ('G', DISABLE,    DIALECT_WARNING_SET_PRAGMA)

typedef struct {
  char                   letter;
  Dialect_Letter_Action  action;
  u32                    classes;
} Gnat_Warning_Letter_Properties;

#define GNAT_WARNING_LETTER_ROW(row_letter, row_action, row_classes)          \
  { .letter  = row_letter,                                                    \
    .action  = DIALECT_LETTER_##row_action,                                   \
    .classes = row_classes },
const Gnat_Warning_Letter_Properties Gnat_Warning_Letter_Table[] = {
  GNAT_WARNING_LETTER_LIST (GNAT_WARNING_LETTER_ROW)
};
#undef GNAT_WARNING_LETTER_ROW
enum { GNAT_WARNING_LETTER_COUNT =
         sizeof Gnat_Warning_Letter_Table
         / sizeof *Gnat_Warning_Letter_Table };
_Static_assert (GNAT_WARNING_LETTER_COUNT == 9,
  "GNAT_WARNING_LETTER_LIST row count");

